std::map<uint32_t, uint32_t> g_decline_census;   // reason*16 + sizeclass -> count, RUN-scoped
std::map<uint64_t, uint32_t> g_size_mismatch;     // what the OTHER-SIZE bucket ASKED for
std::map<uint64_t, uint32_t> g_size_mismatch_reg; // what is registered at that address instead
uint64_t g_only_vs_skipped = 0, g_only_vs_kept = 0;  // ngpu_debug_only_vs: turned away / let through
uint64_t g_skipped_ps = 0;   // draws removed by ngpu_skip_ps, so a leg that skipped nothing says so
// FRAME-GATED DISCRIMINATOR SCHEDULE (ngpu_drop_sched): see the cvar. Parsed
// once; every entry logged, so a malformed one is a report and not a silent
// no-op leg. The counters say how many draws each entry removed - an entry
// that removed 0 draws tested nothing and its shots are two controls. [unsourced, pre-2026-09-23]
struct DropSchedEntry { uint32_t frame = 0; char kind = 'p'; uint32_t high = 0; uint64_t dropped = 0; };
std::vector<DropSchedEntry> g_drop_sched;
bool g_drop_sched_parsed = false;
void ParseDropSched() {
  if (g_drop_sched_parsed) return;
  g_drop_sched_parsed = true;
  const std::string s = REXCVAR_GET(ngpu_drop_sched);
  size_t p = 0;
  while (p < s.size()) {
    size_t e = s.find(',', p);
    if (e == std::string::npos) e = s.size();
    const std::string item = s.substr(p, e - p);
    p = e + 1;
    if (item.empty()) continue;
    const size_t c = item.find(':');
    if (c == std::string::npos || c + 2 > item.size() || (item[c + 1] != 'p' && item[c + 1] != 'v')) {
      REXLOG_INFO("[ngpu] drop schedule: entry '{}' MALFORMED (want F:pHHHHHHHH or F:vHHHHHHHH) - ignored", item);
      continue;
    }
    DropSchedEntry d;
    d.frame = uint32_t(std::strtoul(item.c_str(), nullptr, 10));
    d.kind = item[c + 1];
    d.high = uint32_t(std::strtoul(item.c_str() + c + 2, nullptr, 16));
    g_drop_sched.push_back(d);
    REXLOG_INFO("[ngpu] drop schedule: from frame {} for {} frames drop {} shader {:08X}; shots armed at frame {} (pre) and {} (post)", d.frame, REXCVAR_GET(ngpu_drop_sched_window),
                d.kind == 'p' ? "PIXEL" : "VERTEX", d.high, d.frame - uint32_t(std::max(2, REXCVAR_GET(ngpu_drop_sched_window))) / 2, d.frame + 2);
  }
}
// POSE SIGNATURE beside every shot: the VS float constants c0..c3 (64 bytes)
// of the frame's first colour-writing draw and, when ngpu_pose_vs names one,
// of that vertex shader's first draw (the terrain: its world matrix is
// stable, so c0..c3 move only with the camera). "Near-static camera" was an
// assumption; a pre/post pair is read only when these agree.
struct PoseSig { bool set = false; uint32_t vs = 0; uint32_t c[16] = {}; uint64_t Hash() const { return XXH3_64bits(c, sizeof(c)); } };
PoseSig g_pose_first, g_pose_named;
uint32_t g_pose_frame = ~0u;
// A DUMP FRAME: the ngpu_dump_rts cadence, AND the discriminator schedule's
// pre (F-1) and post (F+2) frames. The RT dump outranks the shot as the
// picture instrument (leg R: seven dumps internally consistent, the shots at
// the same presents 12-65% black), so the windows record dumps as well as
// shots. One helper for every site that used the modulo (five of them).
bool IsDumpFrame(uint32_t frame) {
  const int every = REXCVAR_GET(ngpu_dump_rts);
  if (every > 0 && frame && (frame % uint32_t(every)) == 0) return true;
  for (const auto& e : g_drop_sched)
    if (frame == e.frame - 1 || frame == e.frame + 2) return true;
  return false;
}
bool DropSchedHits(char kind, uint32_t high, uint32_t frame) {
  if (g_drop_sched.empty()) return false;
  const uint32_t w = uint32_t(std::max(1, REXCVAR_GET(ngpu_drop_sched_window)));
  for (auto& d : g_drop_sched)
    if (d.kind == kind && d.high == high && frame >= d.frame && frame < d.frame + w) { ++d.dropped; return true; }
  return false;
}
uint64_t g_comp_depth_forced = 0;  // composite draws whose depth test this run removed
// WHERE THE COMPOSITE'S SAMPLED SLOT CAME FROM. Its pixel shader reads the
// texture named by shared reg 3 and stores it unmodified, and slot 3 holds a
// 1x1 at 1FC40000 in 13 of 20 dumps. Four different sources can fill a fetch
// [unsourced, pre-2026-09-23]
// constant here and only one is the live ring register file; a replayed draw
// has no device to fall back to, so a fallback is a stale read wearing the
// same shape as a real one. Naming the source separates 'the guest bound a
// stub' from 'we read the wrong place'.
std::string g_comp_slot3_latest;
// The state a composite draw carries. Its draws issue and produce NO fragments
// - the target clears to magenta and presents uniformly magenta - so the
// question is which piece of state rejects every one of them. Four can, and
// all four are registers we replay: the colour write mask (RB_COLOR_MASK), the
// depth test (RB_DEPTHCONTROL), the blend (RB_BLENDCONTROL0), and the scissor.
std::map<uint64_t, uint32_t> g_comp_state;
// The same state, over every OTHER surface. 86% of the composite's draws carry
// [unsourced, pre-2026-09-23]
// a zero colour write mask, and a zero mask writes nothing - but that is only
// a finding if the draws that DO render carry a non-zero one. If everything
// reads zero, the register is not reaching the replay and the composite's
// reading says nothing about the composite.
std::map<uint64_t, uint32_t> g_scene_state;
// How many of the first 64 ALU float constants are non-zero at each issued
// draw. A composite quad transformed by an all-zero matrix collapses to a
// point and covers nothing - which is precisely what the composite target
// shows: draws issue, with real shaders, real streams, a full colour write
// mask, and not one pixel changes. The scene surface is the control: if it
// sees constants and the composite does not, the constants are the answer.
uint64_t g_const_zero_comp = 0, g_const_live_comp = 0;
uint64_t g_const_zero_scene = 0, g_const_live_scene = 0;
// Alpha test, the last thing that can throw away every fragment of a draw that
