uint64_t g_atest_comp = 0, g_atest_scene = 0;
std::map<uint32_t, uint32_t> g_atest_ref_comp;
inline int32_t WindowOffsetY(uint32_t v) {
  const uint32_t y = (v >> 16) & 0x7FFF;
  return (y & 0x4000) ? int32_t(y) - 0x8000 : int32_t(y);
}
