  g_resolved_by_fetch[uint64_t((base & 0x1FFFFFFFu) + 0x1000u) | (uint64_t(w) << 32) | (uint64_t(h) << 48)] = rkey;
  if (g_ever_registered.size() < 4096) g_ever_registered.insert((base & 0x1FFFFFFFu) + 0x1000u);
