      static uint32_t sub_logs = 0;
      if (sub_logs < 4) { ++sub_logs; REXLOG_INFO("[ngpu] resolve source: the registers name surface {:08X} colour {:08X}, which has no draws; copying from surface {:08X} colour {:08X} with {} instead", rt->surf, rt->color, best->surf, best->color, best->draws); }
