      REXLOG_INFO("[ngpu] RESOLVE PAIRING (queued params vs LIVE registers at the copy): {} resolves, {} with no live capture, {} surface agrees, {} surface DIFFERS, {} dest agrees, {} dest DIFFERS",
                  g_pair_total, g_pair_nolive, g_pair_surf_ok, g_pair_surf_bad, g_pair_dest_ok, g_pair_dest_bad);
      REXLOG_INFO("[ngpu] CLEAR-BIT PAIRING (clear fix's marker-read bits vs the copy's own RB_COPY_CONTROL): {} agree, {} DISAGREE ({} spurious clears, {} missed clears, {} other), {} unmatched",
                  g_clr_agree, g_clr_disagree, g_clr_spurious, g_clr_missed, g_clr_disagree - g_clr_spurious - g_clr_missed, g_clr_unmatched);
      g_clr_agree = g_clr_disagree = g_clr_spurious = g_clr_missed = g_clr_unmatched = 0;
      g_pair_total = g_pair_nolive = g_pair_surf_ok = g_pair_surf_bad = g_pair_dest_ok = g_pair_dest_bad = 0;
