      const uint32_t drows = dmsaa ? 8u : 16u;   // pixel rows per tile row of the DESTINATION surface (natively drawn 1x)
      const uint32_t dbase = uint32_t(dkey) & 0x7FFu, dtr = (srt->h + drows - 1) / drows;
