bool SplitLoadConstants(uint32_t, uint32_t, uint32_t, const uint32_t*, uint64_t*) { return false; }
bool SplitBatchEnd(const uint32_t*, uint32_t, void (*)(const uint32_t*, uint32_t), bool) { return false; }
